"""Export evidence-backed feed registry and a readable local implementation report."""
import csv,datetime,html,json
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1]
def read(name,default=None):
 p=ROOT/'data'/(name+'.json');return json.loads(p.read_text()) if p.exists() else (default if default is not None else {})
def main():
 now=datetime.datetime.now(datetime.timezone.utc).isoformat();health={r['source']:r for r in read('intake-report').get('sources',[])};registry=[]
 for s in read('sources',[]):
  if not s.get('feed'):continue
  h=health.get(s['id'],{});registry.append({'id':s['id'],'name':s['name'],'endpoint':s['feed'],'adapter':'rss','state':h.get('status','unchecked'),'scope':s.get('municipality') or 'Lokale relevantie controleren','history':'Alleen beschikbare feeditems; geen volledig archief','proposedIntervalMinutes':15 if s['id'].startswith('politie') else 60,'rights':'Privé-signalering van metadata; geen toestemming voor artikeltekst of foto afgeleid uit RSS','latestCheck':read('intake-report').get('runAt'),'received':h.get('receivedInWindow',0)})
 extra=[('koop-sru','Officiële bekendmakingen','https://repository.overheid.nl/sru','koop','tested','26 gemeenten; publicatiedatum en afzender','Gepagineerde zoekopdracht',1440),('vru-incidents','Veiligheidsregio Utrecht','https://vru.nl/incidenten/','vru','tested','Incidentmetadata; datum is incidentdatum','Gepagineerd incidentenarchief',15),('council','Gemeenteraden / OpenBesluitvorming','https://openbesluitvorming.nl/api/search','council','partial','22 gekoppelde gemeenten; vier rechtstreeks controleren','Huidige adapter eerste 24 vergaderingen per gemeente; documenten nog niet verwerkt',360),('ndw','NDW DATEX II','https://opendata.ndw.nu/actueel_beeld.xml.gz','ndw','implemented','Ruime coördinatenselectie; gemeente nog controleren','Actuele situatie; geen zesmaandsarchief',5),('burgernet-kindalerts','Burgernet: AMBER / Vermist Kind','https://services.burgernet.nl/landactiehost/api/v1/alerts','amber','tested','Alleen statusmetadata; geen openbare waarschuwing','Actuele alerts, geen algemene Burgernet-geschiedenis',5),('burgernet-local','Algemene Burgernet-acties','https://www.burgernet.nl/actueel','none','unresolved','Geen openbare algemene feed geverifieerd','Niet beschikbaar in huidige inname',0),('p2000','P2000 / 112-dispatch','https://alarmeringen.nl/utrecht/p2000/','none','unresolved','Geen providerfeed met hergebruiksvoorwaarden vastgesteld','Geen import; dispatch is geen bevestigd incidentartikel',0),('ns-api','NS actuele reisinformatie','https://apiportal.ns.nl/startersguide','none','needs_credentials','Station/traject en actuele geldigheid','Account en productsleutel ontbreken',5)]
 for id,name,url,adapter,state,scope,history,minutes in extra:registry.append(dict(id=id,name=name,endpoint=url,adapter=adapter,state=state,scope=scope,history=history,proposedIntervalMinutes=minutes,rights='Voor productie bronvoorwaarden en inhoudstype vastleggen; metadata-inname is geen beeldlicentie',latestCheck=now,received=''))
 for m in read('municipal-source-discovery',[]):
  registry.append(dict(id='gemeente-'+m['municipality'],name=m['name']+' · website en raad',endpoint=m.get('councilFinalUrl') or m['homepage'],adapter='discovery',state=m.get('councilStatus','unchecked'),scope=m['municipality'],history='Zie municipal-source-discovery.json voor homepage, raadsportalen en koppelingen',proposedIntervalMinutes=360,rights='Primaire feiten; documenten en beelden afzonderlijk beoordelen',latestCheck=m.get('checkedAt'),received=''))
 for i,s in enumerate(read('source-families',[])):
  registry.append(dict(id='coverage-'+str(i),name=s['name'],endpoint=s['url'],adapter='coverage_plan',state=s['state'],scope=s['purpose'],history=s['next'],proposedIntervalMinutes='',rights='Nog per concrete endpoint vastleggen',latestCheck='',received=''))
 (ROOT/'data/feed-registry.json').write_text(json.dumps(registry,ensure_ascii=False,indent=2))
 with (ROOT/'data/feed-registry.csv').open('w') as f:
  writer=csv.DictWriter(f,fieldnames=list(registry[0]));writer.writeheader();writer.writerows(registry)
 koop=read('koop-report');ks=koop.get('sources',[]);inboxes={name:len(read(name,[])) for name in ('inbox','koop-inbox','council-inbox','vru-inbox','ndw-inbox')};e=html.escape
 rows=''.join('<tr>'+''.join('<td>'+e(str(x.get(k,'')))+'</td>' for k in ('municipality','fetched','candidates','hasMore','status'))+'</tr>' for x in ks)
 feeds=''.join('<tr><td>'+e(x['name'])+'</td><td>'+e(x['state'])+'</td><td><a href="'+e(x['endpoint'],quote=True)+'">'+e(x['endpoint'])+'</a></td><td>'+e(x['history'])+'</td></tr>' for x in registry)
 batch=read('processed-source-batch')
 quarter=read('quarter-processing');batch_articles=sorted([a for a in read('articles',[]) if a.get('importBatch')=='quarter-2026-10-11'],key=lambda a:a.get('sourcePublishedAt',''),reverse=True);batch={'processedAt':'11 oktober 2026','visibleAdded':len(batch_articles),'heldForDateCheck':0}
 processed_rows=''.join('<tr><td>'+('<a href="/nieuws/utrecht/artikel/'+e(a['slug'])+'">'+e(a['title'])+'</a>' if a.get('reviewStatus')=='preview' else e(a['title']))+'</td><td>'+e(a.get('sourcePublishedAt') or 'Datum nog controleren')+'</td><td>'+e('Lokale preview' if a.get('reviewStatus')=='preview' else 'Verborgen concept')+'</td><td><a href="'+e(a['sourceUrl'],quote=True)+'">'+e(a['sourceName'])+'</a></td></tr>' for a in batch_articles)
 policy=read('editorial-category-policy')
 topic_rows=''.join('<tr><td>'+e(str(r['userPriority']))+'</td><td>'+e(r['label'])+'</td><td>'+e(r['audiencePotentialHypothesis'])+'</td><td>'+e(r['currentCoverage'])+'</td><td>'+e(r['selectionRule'])+'</td></tr>' for r in policy.get('categories',[]))
 report=f'''<!doctype html><html lang="nl"><meta charset="utf-8"><meta name="robots" content="noindex,nofollow"><meta name="viewport" content="width=device-width,initial-scale=1"><title>PITO — nieuwsaanvoer Utrecht</title><style>body{{margin:0;background:#F5F1ED;color:#2C2C2C;font:17px/1.6 system-ui}}main{{max-width:1100px;margin:40px auto;padding:36px;background:white}}h1{{font-size:42px;line-height:1.15}}h2{{margin-top:42px}}a{{color:#1050C2}}table{{border-collapse:collapse;width:100%;font-size:14px}}td,th{{text-align:left;padding:12px;border-bottom:1px solid #EDE8DF;vertical-align:top;overflow-wrap:anywhere}}.scroll{{overflow:auto}}.lead{{font-size:22px}}.tag{{color:#1050C2;font-weight:700}}code{{white-space:pre-wrap}}@media(max-width:650px){{main{{margin:0;padding:20px}}h1{{font-size:32px}}}}</style><main><p><a href="/nieuws/redactie/signalen?type=bekendmakingen">Open de doorzoekbare broninbox</a> · <a href="/nieuws/utrecht">Naar de nieuwssite</a></p><p class="tag">PITO · BRONNEN & INNAME · 11 OKTOBER 2026</p><h1>Veel meer bronnen.<br>Een controleerbare nieuwsaanvoer.</h1><p class="lead">De hoeveelheid bronmateriaal was niet het probleem. De oude inname las zes RSS-feeds en slechts één pagina per historische zoekopdracht.</p><p>Nu: {len(health)} RSS-feeds getest; {format(sum(x.get('fetched',0) for x in ks),',').replace(',','.')} officiële publicaties opgehaald voor {len(ks)} gemeenten; {len(read('vru-inbox',[]))} VRU-incidenten. Dit zijn bronrecords, geen evenzoveel publiceerbare artikelen. Controleperiode officiële publicaties: {' t/m '.join(koop.get('window',[]))}.</p>
<h2>Drie maanden · gemeentelijke bronkaart</h2><p><a href="/nieuws/redactie/gemeenten">Open het overzicht van alle 26 gemeenten: bronnen, artikelen, maanddekking en hiaten</a></p><h2>Nieuwe artikelen uit gecontroleerde bronnen</h2><p>Verwerkt op {e(batch.get("processedAt",""))}: {batch.get("visibleAdded",0)} nieuwe artikelen in de lokale preview en {batch.get("heldForDateCheck",0)} verborgen concepten zonder bevestigde brondatum. Volledige bronpagina’s gelezen; eigen korte feitelijke teksten, geen overgenomen bronfoto’s. Menselijke eindredactie blijft nodig vóór externe publicatie. Periode: 11 juli t/m 11 oktober 2026. Dit is nog geen volledige verwerking van alle bronnen. <a href="/nieuws/redactie/gemeenten">Bekijk de bronkaart en de artikelen per gemeente</a>.</p><div class="scroll"><table><tr><th>Artikel</th><th>Brondatum</th><th>Status</th><th>Gecontroleerde bron</th></tr>{processed_rows}</table></div><h2>Wat is daadwerkelijk gebouwd?</h2><ul><li>34 RSS-feeds met statuscontrole, bronhostcontrole en samenvoegen van dezelfde URL uit meerdere gemeentefeeds.</li><li>KOOP: publicatiedatum in de zoekopdracht, vervolgpagina’s, begrensde backfill en behoud van eerder gevonden records. Iedere gemeente heeft een eigen dekkingsteller.</li><li>VRU: zesmaandsinname van incidentmetadata met open/gesloten status. Incidentdatum blijft gescheiden van publicatiedatum.</li><li>Burgernet: actuele v1.1-koppeling getest; alleen technische status opgeslagen, geen namen of foto’s. Geen algemene Burgernet-feed.</li><li>Eén uitvoerbare inname-opdracht met procesvergrendeling, afzonderlijke adapterresultaten en gezamenlijke redactionele wachtrij.</li><li>Feitendossier naar ongepubliceerd artikelconcept: een kop alleen is onvoldoende; alinea’s verwijzen naar gecontroleerde feiten en bronlinks.</li></ul>
<h2>De omvorming naar eigen nieuws</h2><ol><li><b>Ophalen:</b> bron-ID, link, brondatum, ophaaldatum, status en versie bewaren. Een raadsvergadering of incidentdatum is niet de publicatiedatum.</li><li><b>Plaats bepalen:</b> afzender of feed levert een kandidaatgemeente; expliciete locatie, plaatsnaam of geometrie bevestigt de relevantie. Landelijk nieuws alleen bij aantoonbare lokale gevolgen.</li><li><b>Samenvoegen:</b> exacte bron-URL’s zijn nu ontdubbeld. Hetzelfde incident in verschillende bronnen koppelen we aan één dossier; automatische clustering over verschillende URL’s moet nog worden toegevoegd.</li><li><b>Selecteren:</b> voorrang aan veiligheid met publieke impact, grote verkeershinder, woonprojecten, besluiten, inspraak en voorzieningen. Losse kleine aanvragen en herhaalde hulpdienstoproepen worden geen hoofdnieuws. Geen quotum per gemeente en geen verzonnen impactscore.</li><li><b>Feiten controleren:</b> lees het oorspronkelijke besluit of bericht. Noteer alleen onderbouwde feiten, aanvraag/ontwerp/besluit, gebeurtenisdatum, onzekerheden en eventuele afloop. Een RTV-verhaal is een signaal; unieke journalistieke informatie vraagt eigen bevestiging of een passende hergebruiksafspraak.</li><li><b>Schrijven:</b> eigen kop, nieuwsintro, feitelijke alinea’s, noodzakelijke context en bronlinks. Geen verzonnen citaten, geen opvultekst en geen mechanisch herschreven bronartikel. De toekomstige taalmodelkoppeling krijgt uitsluitend het gecontroleerde feitendossier.</li><li><b>Controleren en publiceren:</b> menselijke controle, daarna Strapi-concept. Publicatie is een aparte redactionele handeling. Correcties en gesloten meldingen werken door in hetzelfde dossier.</li></ol>
<h2>Tien categorieën: jouw onderzoek verwerkt</h2><p>De onderstaande bezoekerspotentie en volgorde zijn werkhypothesen uit jouw tabel, geen gemeten publieksvoorkeuren. We gebruiken ze om de bronaanvoer te verbreden. Veiligheid krijgt niet automatisch meer gewicht dan wonen of politiek.</p><div class="scroll"><table><tr><th>Prioriteit bronaanvoer</th><th>Categorie</th><th>Potentiehypothese</th><th>Huidige dekking</th><th>Selectieregel</th></tr>{topic_rows}</table></div><p>De redactionele wachtrij krijgt nu onderwerpsuggesties op basis van trefwoorden in de bronkop. Meerdere onderwerpen zijn mogelijk; een ontbrekend trefwoord betekent niet dat het onderwerp ontbreekt. De suggesties moeten worden gecontroleerd en maken geen artikel openbaar. Er zijn geen lege publieksrubrieken aangemaakt.</p><p><b>Toetsen na livegang:</b> vier weken een nulmeting bij voldoende bezoek: vertoningen en doorklikpercentage per positie, betrokken leestijd, terugkerende lezers en agenda-acties. Vergelijk binnen gemeenten en soortgelijke plaatsingen. Neem correcties en verlopen waarschuwingen mee. Metingen zijn nog niet aangesloten; uit de tabel volgen daarom geen nieuwe algoritmegewichten.</p><h2>Welke inhoud hoort waar?</h2><p><b>Nieuws:</b> uitgewerkte verhalen met voldoende feiten. <b>Meldingen:</b> korte, actuele, geverifieerde hinder of waarschuwingen met eindtijd. <b>Wonen & bouwen:</b> projecten, inschrijvingen en plannen; een aanvraag nooit presenteren als definitief besluit. <b>Agenda:</b> PITO-activiteiten per gemeente. Een groot bronarchief geeft keuze; het hoeft niet allemaal op de homepage.</p>
<h2>112, politie en Burgernet</h2><p>De <a href="https://www.politie.nl/rss">officiële politiefeeds</a> zijn gekoppeld voor alle 26 gemeenten plus de provincie. Die bevatten nieuws en mogelijk opsporing of vermissingen. <a href="https://vru.nl/incidenten/">VRU-incidenten</a> leveren bevestigde overheidsmeldingen. P2000 is een alarmeringssignaal en bewijst niet wat ter plaatse is gebeurd. Er is nog geen P2000-provider met geverifieerde feed en hergebruiksovereenkomst aangesloten.</p><p>De <a href="https://www.burgernet.nl/static/Technische_koppelingen_Burgernet-AMBER_Alert_v1_1.pdf">Burgernet-documentatie v1.1</a> betreft AMBER en Vermist Kind Alerts. De geteste actuele koppeling was leeg. De adapter publiceert niets en bewaart geen persoonsgegevens. Een storing betekent nooit dat een actie is beëindigd. Publieke weergave vereist nog gebiedscontrole, vervalbeleid en intrekkingsverwerking.</p>
<h2>Inhoud van de lokale broninboxen</h2><ul>{''.join('<li>'+e(k)+': '+format(v,',').replace(',','.')+'</li>' for k,v in inboxes.items())}</ul><p>Inboxtotalen kunnen oudere bewaarde records bevatten en zijn niet onderling op incidentniveau ontdubbeld. Raadsgegevens en NDW-snapshots zijn eerder opgehaald; de rapporten tonen hun eigen controledatum. De openbare artikelcollectie is niet automatisch uitgebreid met deze bronrecords.</p>
<h2>Zes maanden officiële publicaties, per gemeente</h2><div class="scroll"><table><tr><th>Gemeente</th><th>Opgehaald</th><th>Na eerste filter</th><th>Nog pagina’s?</th><th>Status</th></tr>{rows}</table></div><p>Dit dekt uitsluitend de uitgevoerde gemeentelijke KOOP-query’s, geen compleet archief van alle nieuwsbronnen. De eerste filter is een beperkte uitsluitlijst; ook resterende records kunnen klein, dubbel of niet nieuwswaardig zijn. Gemeentelijke ligging alleen is geen afzender: provinciale en waterschapsbesluiten moeten apart worden toegevoegd.</p>
<h2>Automatisch bijwerken in productie</h2><p>Voorgestelde frequenties in het register zijn configuratieadvies, geen actieve planning. RSS elk kwartier tot uur; gemeentelijke publicaties dagelijks met zeven dagen overlap; raad enkele keren per dag; incidenten frequenter. Houd providerlimieten aan. Gebruik één geplande worker, een wachtrij, herpogingen met wachttijd, meldingen bij bronuitval en een logboek. ETags/Last-Modified, queue-retries en gedistribueerde locks zijn nog productiewerk.</p><p>De lokale opdracht is al uitvoerbaar:</p><pre><code>python3 scripts/news_pipeline.py --adapters rss,vru,amber
python3 scripts/news_pipeline.py --adapters koop --start 2026-04-11 --end 2026-10-11 --max-pages 100
python3 scripts/prepare_news_draft.py feitendossier.json --output concept.json
python3 scripts/import_strapi.py</code></pre><p>De laatste opdracht maakt alleen een importplan van de bestaande artikelcollectie. De nieuwe conceptvoorbereider schrijft een los concept met bewijsdossier; de aansluiting van die bestanden op het definitieve Strapi-model en een automatische schrijfservice is nog niet gerealiseerd. Er is geen API-sleutel gebruikt, geen provider benaderd en niets extern gepubliceerd.</p>
<h2>Resterende gaten, in volgorde</h2><ol><li>Gemeentelijke nieuwsarchieven en raadsdocumenten volledig pagineren; vier ontbrekende raadskoppelingen oplossen. Provinciale Staten, provincie en waterschappen als afzender in KOOP toevoegen.</li><li>Per onderwerp primaire feitenextractie en controle inrichten; een beheerde taalmodelkoppeling toevoegen met herleidbare feit-ID’s, validatie en redactiewachtrij.</li><li>NS productsleutel voor actuele verstoringen; PITO Strapi-agenda aansluiten. NDW-geometrie preciseren naar gemeente en wegvak.</li><li>P2000 en algemene Burgernet-acties: eerst daadwerkelijk beschikbare koppeling en gebruiksvoorwaarden vaststellen. Niet vervangen door gekopieerde commerciële 112-artikelen.</li><li>Water, stroom, gezondheid, weer, onderwijs, corporaties, ondernemers en cultuur aanvullen met specifieke bronadapters. Niet elke website heeft een feed.</li><li>Hostingworker, login/rollen, monitoring, back-ups, beeldrechten en publicatiecontrole vóór livegang. De lokale website blijft noindex.</li></ol>
<h2>Volledig bronregister</h2><p>Machineleesbaar: data/feed-registry.json en data/feed-registry.csv. Onderstaande statussen onderscheiden werkende adapters, ontdekking en nog uit te voeren koppelingen.</p><div class="scroll"><table><tr><th>Bron</th><th>Status</th><th>Endpoint / bronroute</th><th>Historie / beperking</th></tr>{feeds}</table></div><p>Rapport gemaakt: {e(now)}</p></main></html>'''
 (ROOT/'source-intake-report.html').write_text(report)
 print('Bronregister en source-intake-report.html bijgewerkt.')
if __name__=='__main__':main()
